CREATE TABLE IF NOT EXISTS doctor_services(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,doctor_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,duration_minutes SMALLINT UNSIGNED NOT NULL,active TINYINT NOT NULL DEFAULT 1,FOREIGN KEY(doctor_id) REFERENCES doctors(id),INDEX service_doctor(doctor_id,active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS working_hours(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,clinic_id BIGINT UNSIGNED NOT NULL,weekday TINYINT UNSIGNED NOT NULL,opens_at TIME NOT NULL,closes_at TIME NOT NULL,active TINYINT NOT NULL DEFAULT 1,FOREIGN KEY(clinic_id) REFERENCES clinics(id),INDEX clinic_week(clinic_id,weekday,active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS schedule_blocks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,doctor_id BIGINT UNSIGNED NOT NULL,clinic_id BIGINT UNSIGNED NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,reason VARCHAR(500) NOT NULL,kind VARCHAR(20) NOT NULL DEFAULT 'closed',active TINYINT NOT NULL DEFAULT 1,FOREIGN KEY(doctor_id) REFERENCES doctors(id),FOREIGN KEY(clinic_id) REFERENCES clinics(id),INDEX block_range(doctor_id,starts_at,ends_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS appointment_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,doctor_id BIGINT UNSIGNED NOT NULL,booking_id BIGINT UNSIGNED NULL,actor_user_id BIGINT UNSIGNED NULL,actor_admin_id BIGINT UNSIGNED NULL,event_type VARCHAR(80) NOT NULL,details TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(doctor_id) REFERENCES doctors(id),FOREIGN KEY(booking_id) REFERENCES bookings(id),INDEX event_doctor(doctor_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,booking_id BIGINT UNSIGNED NULL,title VARCHAR(190) NOT NULL,body TEXT NOT NULL,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(booking_id) REFERENCES bookings(id),INDEX user_notifications(user_id,read_at,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
